using Alba;
using Spend.Contracts;
using Spend.Slices.Spend;
using Shouldly;
using Xunit;

namespace Spend.IntegrationTests.Slices.Spend;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: state-change. Status: ready.
///
/// This slice's rule lives inside ONE stream, which is what makes it the ordinary case — and the useful
/// contrast with CommitSpendTests next door, whose rule does not.
/// </summary>
public sealed class ReleaseCommitmentTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly Guid Project = SeedData.ProjectId;
    private static readonly Guid Department = SeedData.DepartmentId;

    // A released commitment returns to the available budget
    //   GIVEN Spend Committed(amount=40000)
    //   WHEN  ReleaseCommitment(amount=40000)
    //   THEN  Commitment Released(amount=40000)
    [Fact]
    public async Task AReleasedCommitmentReturnsToTheAvailableBudget()
    {
        await Given(Project,
            new ProjectOpened(Project, Department, "Rewire the hall"),
            new SpendCommitted(Project, Department, 40_000m));

        await WhenPosting(_ =>
        {
            _.Post.Json(new ReleaseCommitment(Project, Department, 40_000m))
                .ToUrl($"/projects/{Project}/release");
            _.StatusCodeShouldBe(204);
        });

        var events = await EventsFor(Project);
        events[^1].ShouldBeOfType<CommitmentReleased>().Amount.ShouldBe(40_000m);
    }

    // A project cannot release more than it committed
    //   GIVEN Spend Committed(amount=40000)
    //   WHEN  ReleaseCommitment(amount=50000)
    //   THEN  error: ReleaseExceedsCommitment
    [Fact]
    public async Task AProjectCannotReleaseMoreThanItCommitted()
    {
        await Given(Project,
            new ProjectOpened(Project, Department, "Rewire the hall"),
            new SpendCommitted(Project, Department, 40_000m));

        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new ReleaseCommitment(Project, Department, 50_000m))
                .ToUrl($"/projects/{Project}/release");
            x.StatusCodeShouldBe(400);
        });

        // THE RULE NAME IS THE OUTCOME. then="error: ReleaseExceedsCommitment" asserts the ProblemDetails
        // Title, which is the same shape Wolverine produces for a FluentValidation failure — so the
        // assertion does not depend on where the rule happened to be enforced.
        result.ReadAsText().ShouldContain(ReleaseCommitmentEndpoint.ExceedsCommitment);

        // AND NOTHING WAS APPENDED. A rejection that still writes is the failure mode a status-code-only
        // assertion cannot see.
        var events = await EventsFor(Project);
        events.Length.ShouldBe(2);
        events.ShouldNotContain(e => e is CommitmentReleased);
    }
}
